async def fetch_profile(user_id):
    async with asyncio.timeout(5):                  # request budget
        for attempt in range(3):
            try:
                async with asyncio.timeout(10):     # per-attempt budget
                    return await upstream.get(user_id)
            except TimeoutError:
                metrics.inc("retries")
                await asyncio.sleep(2 ** attempt)
        raise UpstreamUnavailable(user_id)

scenario.ru:
# Бюджет запроса 5 с СНАРУЖИ, по-попыточный бюджет 10 с ВНУТРИ
async def fetch_profile(user_id):
    async with asyncio.timeout(5):                  # бюджет запроса
        for attempt in range(3):
            try:
                async with asyncio.timeout(10):     # бюджет попытки
                    return await upstream.get(user_id)
            except TimeoutError:
                metrics.inc("retries")
                await asyncio.sleep(2 ** attempt)
        raise UpstreamUnavailable(user_id)
